pub const TYPES: [&str; 6] = ["string", "number", "boolean", "color", "enum", "asset"];

/// §5c's rules for a schema, each refused in its own sentence. `colour`
/// answers whether G-12 takes a `color` entry's default (spec §11 G-25).
pub(crate) fn check_schema(
    schema: &Value,
    colour: &dyn Fn(&str) -> bool,
) -> Result<(), Diagnostic> {
    let Some(entries) = schema.as_object() else {
        return Err(Diagnostic::error("schema must be an object"));
    };
    if entries.len() > MAX_PROPS {
        return Err(Diagnostic::error(format!(
            "schema has {} keys; the most is {MAX_PROPS}",
            entries.len()
        )));
    }
    for (key, entry) in entries {
        check_entry(key, entry, colour).map_err(Diagnostic::error)?;
    }
    Ok(())
}

/// Each string `default` of a `type: "color"` entry, in schema order — what
/// `check_schema`'s `colour` is asked about. Checks nothing else.
pub(crate) fn colour_defaults(schema: &Value) -> Vec<String> {
    let Some(entries) = schema.as_object() else {
        return Vec::new();
    };
    entries
        .values()
        .filter(|entry| entry.get("type").and_then(Value::as_str) == Some("color"))
        .filter_map(|entry| entry.get("default").and_then(Value::as_str))
        .map(str::to_string)
        .collect()
}

fn check_entry(key: &str, entry: &Value, colour: &dyn Fn(&str) -> bool) -> Result<(), String> {
    if !is_name(key) {
        return Err(format!(
            "schema key \"{key}\" is not a name (letters, digits and _, starting with a letter or _, at most 32 characters)"
        ));
    }
    let Some(kind) = entry.get("type").and_then(Value::as_str) else {
        return Err(format!("schema.{key} must be an object with a type"));
    };
    if !TYPES.contains(&kind) {
        return Err(format!(
            "schema.{key}.type \"{kind}\" is not one of string, number, boolean, color, enum, asset"
        ));
    }
    if kind == "enum" {
        let good = entry
            .get("options")
            .and_then(Value::as_array)
            .is_some_and(|o| {
                (1..=MAX_OPTIONS).contains(&o.len()) && o.iter().all(Value::is_string)
            });
        if !good {
            return Err(format!("schema.{key}.options must be 1–32 strings"));
        }
    }
    let Some(default) = entry.get("default") else {
        return Err(format!("schema.{key} has no default"));
    };
    let fits = match kind {
        "string" => default
            .as_str()
            .is_some_and(|s| s.chars().count() <= MAX_STRING),
        "color" => default.as_str().is_some_and(colour),
        _ => fits(kind, entry, default),
    };
    if !fits {
        return Err(format!("schema.{key}.default {default} is not a {kind}"));
    }
    if let Some(animate) = entry.get("animate").filter(|a| !a.is_boolean()) {
        return Err(format!("schema.{key}.animate {animate} is not a boolean"));
    }
    Ok(())
}

fn is_name(key: &str) -> bool {
    let mut chars = key.chars();
    let head = chars
        .next()
        .is_some_and(|c| c.is_ascii_alphabetic() || c == '_');
    head && key.len() <= 32 && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

/// Whether `value` is of the entry's `kind` (render time: a string's length
/// is not checked).
fn fits(kind: &str, entry: &Value, value: &Value) -> bool {
    match kind {
        "string" | "color" => value.is_string(),
        "number" => value.as_f64().is_some_and(f64::is_finite),
        "boolean" => value.is_boolean(),
        "enum" => options(entry).contains(value),
        "asset" => value.is_string() || value.is_null(),
        _ => false,
    }
}

fn options(entry: &Value) -> Vec<Value> {
    entry
        .get("options")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default()
}
